import re

def get_demo_pair(text,n):
    # locate demo pair block and parse input/output dimensions/data
    pat=rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|$)'
    m=re.search(pat,text,re.S)
    if not m: return None
    h,w,ins,oh,ow,outs=m.groups(); h,w,oh,ow=map(int,(h,w,oh,ow))
    I=[[int(x) for x in line.split()] for line in ins.strip().splitlines()]
    O=[[int(x) for x in line.split()] for line in outs.strip().splitlines()]
    return I,O
