def tiles_from_horizontal(G):
  # assumes horiz row of 5x5 tiles separator col6
  cuts=[c for c in range(len(G[0])) if all(row[c]==6 for row in G)]
  starts=[0]+[c+1 for c in cuts]; ends=cuts+[len(G[0])]
  return [np.array([r[a:b] for r in G]) for a,b in zip(starts,ends)]
def tiles_from_vertical(G):
  cuts=[r for r in range(len(G)) if all(x==6 for x in G[r])]
  starts=[0]+[r+1 for r in cuts]; ends=cuts+[len(G)]
  return [np.array(G[a:b]) for a,b in zip(starts,ends)]
def input_tiles(I):
  # if 11x11 2x2 panels
  if len(I)==11 and len(I[0])==11:
    return [np.array([row[:5] for row in I[:5]]), np.array([row[6:] for row in I[:5]]),np.array([row[:5] for row in I[6:]]),np.array([row[6:] for row in I[6:]])]
  if len(I)==5: return tiles_from_horizontal(I)
  return tiles_from_vertical(I)
def out_tiles(O):
  if len(O)==5: return tiles_from_horizontal(O)
  return tiles_from_vertical(O)
